package org.openidentity.samples.adldap;

import com.unboundid.ldap.listener.*;import com.unboundid.ldap.sdk.*;
import jakarta.servlet.http.HttpSession;import org.openidentity.ad.*;import org.openidentity.ad.ldap.*;import org.openidentity.auth.*;import org.openidentity.core.*;
import org.springframework.boot.*;import org.springframework.boot.autoconfigure.SpringBootApplication;import org.springframework.context.annotation.Bean;import org.springframework.web.bind.annotation.*;
import java.nio.file.*;import java.security.SecureRandom;import java.util.*;

@SpringBootApplication @RestController
public class AdLdapSampleApplication {
 static final String AD="LDAP_VERIFIED_AD_PRINCIPAL",PENDING="OPENIDENTITY_AD_LDAP_PENDING",RESOLVED="OPENIDENTITY_AD_LDAP_RESOLVED";
 record Pending(VerifiedAdPrincipal principal,ExternalAdBindingV1.Binding binding,byte[] challenge,byte[] audience,byte[] nonce,byte[] contextHash){}
 private final FileCanonicalIdentityStateRepository states;private final InMemoryExternalAdBindingRegistry registry;private final InMemoryExternalAdBindingRegistry.Policy policy;private final Oi015Verifier verifier;private final AdPrincipalResolver resolver;
 public AdLdapSampleApplication(FileCanonicalIdentityStateRepository states,InMemoryExternalAdBindingRegistry registry,InMemoryExternalAdBindingRegistry.Policy policy,Oi015Verifier verifier,AdPrincipalResolver resolver){this.states=states;this.registry=registry;this.policy=policy;this.verifier=verifier;this.resolver=resolver;}
 public static void main(String[] a){SpringApplication.run(AdLdapSampleApplication.class,a);}
 @Bean static FileCanonicalIdentityStateRepository states(){return new FileCanonicalIdentityStateRepository(Path.of(env("OPENIDENTITY_STATE_DIR","../../dev/openidentity-state")));}
 @Bean static InMemoryExternalAdBindingRegistry registry(){return new InMemoryExternalAdBindingRegistry(Path.of(env("OPENIDENTITY_AD_LDAP_BINDING_STORE","../../dev/openidentity-ad-ldap-bindings.store")));}
 @Bean(destroyMethod="shutDown") static InMemoryDirectoryServer ldapServer()throws Exception{var cfg=new InMemoryDirectoryServerConfig("dc=oi-test,dc=internal");cfg.setSchema(null);cfg.addAdditionalBindCredentials("cn=svc,dc=oi-test,dc=internal","secret");var ds=new InMemoryDirectoryServer(cfg);ds.startListening();ds.add(new Entry("dc=oi-test,dc=internal",new Attribute("objectClass","top","domain"),new Attribute("dc","oi-test")));ds.add(new Entry("cn=Alice,dc=oi-test,dc=internal",new Attribute("objectClass","top","person"),new Attribute("cn","Alice"),new Attribute("sn","Test"),new Attribute("userPrincipalName","alice@OI-TEST.INTERNAL"),new Attribute("objectGUID",guid()),new Attribute("userAccountControl","512")));return ds;}
 @Bean static AdPrincipalResolver resolver(InMemoryDirectoryServer ds){return new LdapAdPrincipalResolver(new LdapAdPrincipalResolver.Profile("lab","127.0.0.1",ds.getListenPort(),"dc=oi-test,dc=internal","cn=svc,dc=oi-test,dc=internal","secret",dir(),false));}
 @Bean static InMemoryExternalAdBindingRegistry.Policy policy(FileCanonicalIdentityStateRepository states){return new InMemoryExternalAdBindingRegistry.Policy(){public boolean directoryTrusted(byte[] d){return Arrays.equals(d,dir());}public boolean serviceAllowed(byte[] d,String s){return "openidentity-ad-link-service".equals(s);}public boolean mechanismAllowed(byte[] d,int m){return m==ExternalAdBindingV1.KERBEROS_SPNEGO;}public boolean identityActive(byte[] id){var s=states.resolve(id);return s!=null&&s.active();}public long currentAuthenticationGeneration(byte[] id){var s=states.resolve(id);if(s==null)throw new IllegalArgumentException("identity");return s.authenticationAuthority().generation();}};}
 @Bean static Oi015Verifier verifier(FileCanonicalIdentityStateRepository states){return new Oi015Verifier(new CanonicalAuthenticationStateResolver(states),300);}
 @GetMapping("/") Map<String,Object> home(HttpSession s){var r=(InMemoryExternalAdBindingRegistry.Resolved)s.getAttribute(RESOLVED);if(r!=null)return base("AUTHENTICATED",Map.of("identity",hex(r.identity()),"bindingStatus","ACTIVE"));return base("UNBOUND",Map.of("login","/ldap/login"));}
 @GetMapping("/ldap/login") Map<String,Object> login(HttpSession s){var v=resolver.resolve(new AdAuthenticationEvidence("lab","alice@OI-TEST.INTERNAL","openidentity-ad-link-service",ExternalAdBindingV1.KERBEROS_SPNEGO,true,Map.of("authentication","simulated-upstream")));s.setAttribute(AD,v);try{var r=registry.resolve(ExternalAdPrincipalBridge.registryPrincipal(v),System.currentTimeMillis()/1000,policy);s.setAttribute(RESOLVED,r);return base("RESOLVED",Map.of("identity",hex(r.identity()),"objectGuidHex",hex(v.objectGuid())));}catch(ExternalAdBindingException e){if(e.error()!=ExternalAdBindingError.BINDING_NOT_FOUND)throw e;return base("LDAP_PRINCIPAL_RESOLVED",Map.of("authenticatedPrincipal","alice@OI-TEST.INTERNAL","objectGuidHex",hex(v.objectGuid()),"next","GET /openidentity/link/begin?identity=<64-hex OpenIdentity ID>"));}}
 @GetMapping("/openidentity/link/begin") Map<String,String> begin(@RequestParam("identity")String identity,HttpSession s){var v=(VerifiedAdPrincipal)s.getAttribute(AD);if(v==null)throw new IllegalStateException("LDAP principal resolution required");byte[] id=HexFormat.of().parseHex(identity);if(id.length!=32)throw new IllegalArgumentException("identity");var canonical=states.resolve(id);if(canonical==null)throw new IllegalArgumentException("identity not found");long now=System.currentTimeMillis()/1000,gen=policy.currentAuthenticationGeneration(id);var b=new ExternalAdBindingV1.Binding(id,v.directoryId(),v.objectGuid(),v.serviceId(),now,null,gen);byte[] challenge=random(32),aud=random(32),nonce=random(32),ctx=ExternalAdBindingV1.encodeContext(1,b,v.authenticationMechanism(),challenge,null),hash=ExternalAdBindingV1.contextHash(ctx);s.setAttribute(PENDING,new Pending(v,b,challenge,aud,nonce,hash));return Map.of("purpose","openidentity.external-ad.bind","contextHashHex",hex(hash),"audienceHex",hex(aud),"nonceHex",hex(nonce),"stateHashHex",hex(canonical.stateHash()),"authenticationGeneration",Long.toString(gen));}
 @PostMapping(value="/openidentity/link/complete",consumes="text/plain") Map<String,Object> complete(@RequestBody String securedHex,HttpSession s){var p=(Pending)s.getAttribute(PENDING);if(p==null)throw new IllegalStateException("No pending AD LDAP binding ceremony");var secured=Oi015Codec.decode(HexFormat.of().parseHex(securedHex.trim()));var vr=verifier.tryVerify(secured,p.audience(),"openidentity.external-ad.bind",p.nonce(),p.contextHash(),System.currentTimeMillis()/1000);if(!vr.valid())throw new ExternalAdBindingException(vr.contextMismatch()?ExternalAdBindingError.BINDING_CONTEXT_MISMATCH:ExternalAdBindingError.BINDING_AUTHORIZATION_INVALID);var principal=ExternalAdPrincipalBridge.registryPrincipal(p.principal());var state=registry.bind(principal,p.binding().identity(),p.binding().createdAt(),p.binding().expiresAt(),p.challenge(),new InMemoryExternalAdBindingRegistry.Authorization(true,"openidentity.external-ad.bind",true,false),policy);var resolved=registry.resolve(principal,System.currentTimeMillis()/1000,policy);s.setAttribute(RESOLVED,resolved);s.removeAttribute(PENDING);return base("BOUND",Map.of("identity",hex(resolved.identity()),"bindingId",hex(state.bindingId()),"next","/"));}
 static Map<String,Object> base(String status,Map<String,Object> extra){var m=new LinkedHashMap<String,Object>();m.put("status",status);m.put("provider","LDAP_COMPATIBILITY_HARNESS");m.put("principalResolution","LDAP");m.put("productionAuthentication",false);m.putAll(extra);return m;}
 static byte[] dir(){return HexFormat.of().parseHex("d0d1d2d3d4d5d6d7d8d9dadbdcdddedf");}static byte[] guid(){return HexFormat.of().parseHex("00112233445566778899aabbccddeeff");}static byte[] random(int n){byte[] b=new byte[n];new SecureRandom().nextBytes(b);return b;}static String hex(byte[] b){return HexFormat.of().formatHex(b);}static String env(String n,String d){String v=System.getenv(n);return v==null||v.isBlank()?d:v;}
}